"""Keep the Help guide aligned with the shipped analysis catalogue."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1];catalog=json.loads((root/'src/analysis-catalog.json').read_text());brief=dict(line.split('|',1) for line in (root/'src/analysis-definitions.txt').read_text().splitlines() if line)
p=root/'src/model-guide.json';entries=[e for e in json.loads(p.read_text()) if not e['id'].startswith('advanced-')]
category={'T-tests':'means','Proportions & categorical tests':'association','Nonparametric tests':'means','ANOVA & ANCOVA':'means','Regression':'regression','Multilevel & panel models':'regression','Time series':'time','Survival analysis':'regression','Scales & dimension reduction':'sem'}
for m in catalog:
 group=m['group'];caution='Check the design, independence assumptions, missing values and diagnostic output. A fitted association alone does not establish causation.'
 if group=='Time series':caution='Use unique regularly spaced numeric time points with no gaps or missing outcomes. Check stationarity, seasonality and residual dependence. Rolling-origin comparisons are one-step forecasts; future predictors must be supplied for explanatory forecasts.'
 if group=='Survey inference & missing data':caution='A defensible survey design or missing-data model is required. Weights alone do not identify the sampling design, and observed missingness patterns do not establish MAR.'
 if group=='Predictive modeling':caution='Random train/holdout splits assume independent rows. Temporal and clustered data require design-aware validation. Clustering is exploratory and depends on scaling and the chosen number of clusters.'
 if group=='Data management':caution='Review keys, output rows and variable types in the preview before applying it. Undo restores the previous dataset; data operations include all rows, regardless of active filters.'
 if group=='Multilevel & panel models':caution='Check cluster count, within-group variation, model identification and convergence. Random effects need defensible exogeneity assumptions; dynamic GMM additionally requires valid instruments and serial-correlation checks.'
 data='Select '+', '.join(m['inputs'])+' on Setup; each row must represent the observation or measurement required by this design.' if m['inputs'] else 'Use the named planning inputs; a raw dataset is not required.'
 if m['summary']:data+=' Summary-statistics or count input is available; paired t-tests require summaries of the within-pair differences.' if m['id']=='summary_tp' else ' Summary-statistics or count input is available where shown.'
 pkg=(m['packages'] or ['stats'])[0]
 entries.append(dict(id='advanced-'+m['id'],category=category.get(group,'other'),title=m['title'],question='When should I use '+m['title']+'?',what=brief[m['id']],use='Use this dedicated '+group.lower()+' page when its outcome type and study design match your question. '+brief[m['id']],data=data,read='Read the analysis sample first, then estimates, uncertainty and test or evaluation statistics. Diagnostics and Predictions have separate subtabs when applicable.',caution=caution,example={'Time series':'Forecast monthly public-service demand and compare one-step errors with simple benchmark forecasts.','Data management':'Join respondent records to district characteristics using verified district identifiers.','Survival analysis':'Study time until an event while retaining respondents whose event time is right-censored.','Predictive modeling':'Predict a binary survey outcome or a numeric score, evaluating predictions on independent held-out respondents.'}.get(group,'Analyze a survey, experiment or observational study using variables and observation units appropriate to this method.'),route={'tab':'analysis','analysisId':m['id'],'analysisSub':'Setup'},sources=[{'label':pkg+' package documentation','url':'https://cran.r-project.org/package='+pkg}] if pkg!='stats' else [{'label':'R statistical methods documentation','url':'https://stat.ethz.ch/R-manual/R-devel/library/stats/html/00Index.html'}],aliases=m['id']+' '+group))
p.write_text(json.dumps(entries,ensure_ascii=False,indent=2)+'\n');print(len(entries),'guide entries')
